    pub fn orig_head_name(&self) -> Option<&str> {
        let name_bytes =
            unsafe { crate::opt_bytes(self, raw::git_rebase_orig_head_name(self.raw)) };
        name_bytes.and_then(|s| str::from_utf8(s).ok())
    }

    /// Gets the original HEAD id for merge rebases.
