#[inline(never)]
fn options(calls: &Cell<usize>) -> git2::ApplyOptions<'_> {
    let mut opts = git2::ApplyOptions::new();
    opts.delta_callback(|_| {
        calls.set(calls.get() + 1);
        true
    });
    opts
}

